-- Source data (a copy of the payments database). Do not edit this file.
-- Times are UTC.

CREATE TABLE payments (
    payment_id   INTEGER PRIMARY KEY,
    user_id      TEXT    NOT NULL,
    amount_cents INTEGER NOT NULL,
    status       TEXT    NOT NULL,  -- 'completed', 'failed' or 'refunded'
    created_at   TEXT    NOT NULL   -- 'YYYY-MM-DD HH:MM:SS'
);

-- Events sent by the payment processor. It can send the same event more than once.
CREATE TABLE payment_events (
    event_id   INTEGER PRIMARY KEY,
    payment_id INTEGER NOT NULL REFERENCES payments (payment_id),
    event_type TEXT    NOT NULL,  -- 'created', 'settled', 'failed' or 'refunded'
    created_at TEXT    NOT NULL
);


